import numpy as np, collections, itertools
l=open("opt2.xyz").read().split("\n");n=int(l[0])
sym=[];xyz0=[]
for i in range(2,2+n):
    q=l[i].split();sym.append(q[0]);xyz0.append([float(z) for z in q[1:4]])
xyz0=np.array(xyz0)
cov={'H':0.35,'C':0.77,'N':0.72,'P':1.08,'Cl':1.02,'Ge':1.22,'Rh':1.42}
adj=collections.defaultdict(list)
for i in range(n):
    for j in range(i+1,n):
        if np.linalg.norm(xyz0[i]-xyz0[j])<(cov[sym[i]]+cov[sym[j]])*1.3: adj[i].append(j);adj[j].append(i)
def group(a,block):
    g={a};st=[a]
    while st:
        x=st.pop()
        for b in adj[x]:
            if b==block or b in g or b in (3,5): continue
            g.add(b);st.append(b)
    return sorted(g)
# torsions: (pivotA, pivotB) rotate group(pivotB, pivotA)
# aryl: N1 - C19 ; iPr1: C15-C16 ; iPr2: find other iPr CH attached to C11
ar=group(19,1)
ipr=[]
for c in adj[19]:
    if sym[c]!='C': continue
    for d in adj[c]:
        if sym[d]=='C' and d!=19 and len([x for x in adj[d] if sym[x]=='C'])==3:
            ipr.append((c,d))
print("ipr pivots",ipr)
tors=[(1,19,ar)]+[(a,b,group(b,a)) for a,b in ipr]
for t in tors: print(t[0],t[1],len(t[2]))
def rotm(ax,th):
    ax=ax/np.linalg.norm(ax)
    K=np.array([[0,-ax[2],ax[1]],[ax[2],0,-ax[0]],[-ax[1],ax[0],0]])
    return np.eye(3)+np.sin(th)*K+(1-np.cos(th))*K@K
def apply(xyz,degs):
    p=xyz.copy()
    for (a,b,g),dg in zip(tors,degs):
        R=rotm(p[b]-p[a],np.radians(dg))
        p[g]=(R@(p[g]-p[a]).T).T+p[a]
    return p
# scoring: clashes between aryl-sidechain atoms and the rest (vdW-based)
vdw={'H':1.2,'C':1.7,'N':1.55,'P':1.8,'Cl':1.75,'Ge':2.1,'Rh':2.0}
movable=sorted(set(ar))
rest=[i for i in range(n) if i not in movable]
rv=np.array([vdw[sym[i]] for i in movable]); rr=np.array([vdw[sym[i]] for i in rest])
lim=(rv[:,None]+rr[None,:])*0.80
# also intra-aryl clashes handled by keeping ipr rotation only
best=None
grid=range(0,360,20)
for d0 in range(0,360,15):
    for d1 in grid:
        for d2 in grid:
            p=apply(xyz0,[d0,d1,d2])
            d=np.linalg.norm(p[movable][:,None]-p[rest][None],axis=2)
            # ignore bonded N-C19
            sc=np.sum(np.clip(lim-d,0,None)**2)
            if best is None or sc<best[0]: best=(sc,(d0,d1,d2))
print("best",best)
p=apply(xyz0,best[1])
with open("rot2.xyz","w") as f:
    f.write(f"{n}\nrot2\n")
    for s,q in zip(sym,p): f.write(f"{s} {q[0]:.4f} {q[1]:.4f} {q[2]:.4f}\n")
d=np.linalg.norm(p[movable][:,None]-p[rest][None],axis=2); print("min",d.min())
